/*
 * ST_ASSISTANT_VERIFIED_CAPACITY_SEARCH_V1
 *
 * Battery capacity must be established from published
 * product data, not generated by an AI model.
 *
 * Distinguish individual configurations and never
 * substitute a different mAh value as an exact match.
 */

type CapacityVariant = {
  id: string;
  size?: string | null;
  variantName?: string | null;
  attributes?: Record<string, unknown> | null;
};

type CapacityProduct<T extends CapacityVariant> = {
  name: string;
  description?: string | null;
  category?: string | null;
  variants: T[];
};

export type AssistantCapacityRequest = {
  kind: "power_bank";
  capacityMah: number;
};

function normalize(value: string): string {
  return value
    .normalize("NFKD")
    .replace(/[\u0300-\u036f\u064B-\u065F\u0670]/g, "")
    .replace(/[أإآٱ]/g, "ا")
    .replace(/[٠-٩]/g, (digit) =>
      String(digit.charCodeAt(0) - 0x0660)
    )
    .replace(/[۰-۹]/g, (digit) =>
      String(digit.charCodeAt(0) - 0x06f0)
    )
    .toLowerCase();
}

const POWER_BANK_KIND =
  /\b(?:power\s*banks?|powerbanks?|powr\s*banks?|powerbnks?|portable\s+chargers?|battery\s+packs?|batter(?:ie|y)s?\s+externes?|chargeurs?\s+portables?)\b|(?:باور\s*بانك|شاحن\s*متنقل|بطاري(?:ة|ه)\s*متنقل(?:ة|ه))/;

const CAPACITY_WITH_UNIT =
  /(^|[^a-z0-9])([0-9]{1,3}(?:[ ,.]*[0-9]{3}){1,2})\s*(?:m\s*a\s*h|milliamps?(?:\s*hours?)?|milliamperes?(?:\s*(?:hours?|heures?))?|ميلي\s*امبير(?:\s*ساع[ةه])?)(?![a-z0-9])/g;

function capacitiesIn(value: string): Set<number> {
  const result = new Set<number>();

  for (const match of normalize(value).matchAll(
    CAPACITY_WITH_UNIT
  )) {
    const number = Number(
      match[2].replace(/[^0-9]/g, "")
    );

    if (
      Number.isInteger(number) &&
      number >= 1000 &&
      number <= 100000
    ) {
      result.add(number);
    }
  }

  return result;
}

function merge(
  target: Set<number>,
  source: Iterable<number>,
) {
  for (const value of source) {
    target.add(value);
  }
}

function variantCapacities(
  variant: CapacityVariant,
): Set<number> {
  const result = capacitiesIn(
    [
      variant.size ?? "",
      variant.variantName ?? "",
    ].join(" ")
  );

  const attributes = variant.attributes;

  if (
    !attributes ||
    typeof attributes !== "object" ||
    Array.isArray(attributes)
  ) {
    return result;
  }

  for (const [key, value] of Object.entries(attributes)) {
    if (
      key === "__technical_specs" &&
      Array.isArray(value)
    ) {
      for (const entry of value) {
        if (
          !entry ||
          typeof entry !== "object"
        ) {
          continue;
        }

        const item = entry as {
          name?: unknown;
          value?: unknown;
        };

        if (
          typeof item.value === "string"
        ) {
          merge(
            result,
            capacitiesIn(item.value),
          );
        }

        if (
          typeof item.name === "string"
        ) {
          merge(
            result,
            capacitiesIn(item.name),
          );
        }
      }
    } else if (
      typeof value === "string" ||
      typeof value === "number"
    ) {
      merge(
        result,
        capacitiesIn(String(value)),
      );
    }
  }

  return result;
}

export function parsePowerBankCapacityRequest(
  question: string,
): AssistantCapacityRequest | null {
  if (
    !question.trim() ||
    question.length > 500
  ) {
    return null;
  }

  const text = normalize(question);

  if (!POWER_BANK_KIND.test(text)) {
    return null;
  }

  // Leave order tracking, comparisons and complex
  // budget decisions to their established handlers.
  if (
    /\b(?:my order|track|refund|warranty|store hours|opening hours|your address|your location|compare|versus|vs|budget|under \$|below \$)\b/.test(
      text
    )
  ) {
    return null;
  }

  const capacities = capacitiesIn(text);

  if (capacities.size !== 1) {
    return null;
  }

  const [capacityMah] = capacities;

  return {
    kind: "power_bank",
    capacityMah,
  };
}

export function matchingPowerBankCapacityVariants<
  T extends CapacityVariant,
>(
  product: CapacityProduct<T>,
  capacityMah: number,
): T[] {
  const identity = normalize(
    `${product.name} ${product.category ?? ""}`
  );

  if (!POWER_BANK_KIND.test(identity)) {
    return [];
  }

  // A power-bank cable or carrying case is not
  // itself a power bank.
  const category = normalize(product.category ?? "");

  if (
    !POWER_BANK_KIND.test(category) &&
    /\b(?:cables?|cases?|covers?|pouches?|bags?|holders?|stands?)\b/.test(
      normalize(product.name)
    )
  ) {
    return [];
  }

  const productCapacities = capacitiesIn(
    `${product.name} ${product.description ?? ""}`
  );

  const productEvidenceMatches =
    productCapacities.size === 1 &&
    productCapacities.has(capacityMah);

  const matches: T[] = [];

  for (const variant of product.variants) {
    const specific = variantCapacities(variant);

    if (specific.size > 0) {
      if (
        specific.size === 1 &&
        specific.has(capacityMah) &&
        (
          productCapacities.size !== 1 ||
          productEvidenceMatches
        )
      ) {
        matches.push(variant);
      }
    } else if (productEvidenceMatches) {
      // Product-wide capacity can be used only when
      // exactly one capacity is stated.
      matches.push(variant);
    }
  }

  return matches;
}
